$(document).ready(function(){$.ajax("version.json",{error:function(e,t){createAlert({title:"<strong>Error getting version.json!</strong>",message:e.statusText})},dataType:"text",success:function(e,t){var r=stripJsonOfComments(e),o=JSON.parse(r);window.version=o.interface,$("#livemap_version").text(window.version),$.ajax("https://raw.githubusercontent.com/TGRHavoc/live_map-interface/master/version.json",{error:function(e,t){createAlert({title:"<strong>Error latest version for check!</strong>",message:e.statusText})},dataType:"text",success:function(e,t){var r=stripJsonOfComments(e),o=JSON.parse(r);window.compareVersions(window.version,o.interface)<0?createAlert({title:"Update available",message:`An update is available (${window.version} -> ${o.interface}). Please download it <a style='color: #000;' href='https://github.com/TGRHavoc/live_map-interface'>HERE.</a>`}):console._log("Up to date or, a higher version")}})}})});